ValidationRule.errorConditionFormula:
OR(
    AND(
        ISPICKVAL(Modalidad__c, 'Con factura'),
        OR(
            ISBLANK(RFC__c),
            NOT(REGEX(UPPER(TRIM(RFC__c)), "^[A-Z&Ñ]{3,4}[0-9]{2}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])[A-Z0-9]{3}$"))
        )
    ),
    AND(
        NOT(ISPICKVAL(Modalidad__c, 'Con factura')),
        NOT(ISBLANK(RFC__c))
    )
)
